insert into content.content_block (place_id,section,slot,ord,body,fact_refs,status,author,field) values
('area:evasion-mont-blanc','meta','line',0,'Évasion Mont Blanc | Linked ski areas | Snow Catchers','{}'::text[],'review','loader','title'),
('area:evasion-mont-blanc','meta','line',1,'How Megève, Saint-Gervais, Combloux and La Giettaz share one pass across two separate lift networks, which base reaches which slopes, how much snow falls at the height these villages ski, what the pass costs, and what the area is like for boarders, families, food and evenings.','{}'::text[],'review','loader','description'),
('area:evasion-mont-blanc','meta','line',2,'France','{}'::text[],'review','loader','crumbs.0.label'),
('area:evasion-mont-blanc','meta','line',3,'Linked ski areas','{}'::text[],'review','loader','crumbs.1.label'),
('area:evasion-mont-blanc','meta','line',4,'Northern Alps','{}'::text[],'review','loader','crumbs.2.label'),
('area:evasion-mont-blanc','hero','lead',0,'Évasion Mont Blanc is one pass over the hills west of Mont Blanc, from Megève and Saint-Gervais to Combloux and La Giettaz, which the operator puts at {{f:F000490}} of piste once Les Contamines is counted. On the snow it is two separate networks, and neither climbs high: skiresort.com puts the lifts between {{f:F000510|n}} and {{f:F000511}}. Megève grew into a winter resort around the Rothschild family, and in {{f:F000506}} Noémie de Rothschild opened the Domaine du Mont d''Arbois above the village.',array['F000490','F000506','F000510','F000511']::text[],'review','loader','hero.lead'),
('area:evasion-mont-blanc','stats','line',0,'{{f:F000508}}',array['F000508']::text[],'review','loader','stats.0.v'),
('area:evasion-mont-blanc','stats','line',1,'of linked piste on skiresort.com, in two networks that do not meet; the operator''s {{f:F000490}} adds Les Contamines',array['F000490']::text[],'review','loader','stats.0.t'),
('area:evasion-mont-blanc','stats','line',2,'{{f:F000510|n}} to {{f:F000511}}',array['F000510','F000511']::text[],'review','loader','stats.1.v'),
('area:evasion-mont-blanc','stats','line',3,'from Saint-Gervais to the top of the Mont Joly chair, on skiresort.com','{}'::text[],'review','loader','stats.1.t'),
('area:evasion-mont-blanc','stats','line',4,'{{f:F000551}}',array['F000551']::text[],'review','loader','stats.2.v'),
('area:evasion-mont-blanc','stats','line',5,'main lifts in the map data, {{f:F000552}} of them drags',array['F000552']::text[],'review','loader','stats.2.t'),
('area:evasion-mont-blanc','stats','line',6,'{{f:F000535}}',array['F000535']::text[],'review','loader','stats.3.v'),
('area:evasion-mont-blanc','stats','line',7,'for six days, adult, 2026/27, or {{f:F000536}} bought online at least ten days ahead',array['F000536']::text[],'review','loader','stats.3.t'),
('area:evasion-mont-blanc','network','heading',0,'One pass, two networks','{}'::text[],'review','loader','network.h2'),
('area:evasion-mont-blanc','network','para',0,'The larger network runs from Megève to Saint-Gervais. Rochebrune and Côte 2000 rise on the south side of Megève, Mont d''Arbois on the east, and from Mont d''Arbois the lifts cross to Le Bettex above Saint-Gervais, to Princesse above Demi-Quartier and over Mont Joux to Saint-Nicolas-de-Véroce. The smaller network, Les Portes du Mont-Blanc, joins Megève''s Le Jaillet sector to Combloux and La Giettaz on the north side of the village.','{}'::text[],'review','loader','network.paras.0'),
('area:evasion-mont-blanc','network','para',1,'Megève sits between the two, and no lift or piste crosses it from Le Jaillet to Rochebrune or Mont d''Arbois. Guide Ski and the map data agree on this, so moving from one network to the other means the free Meg-Bus or the car. Les Contamines-Hauteluce shares the pass but lies further up its own valley, reached by road.','{}'::text[],'review','loader','network.paras.1'),
('area:evasion-mont-blanc','network','para',2,'Inside the Megève network the weak point is the crossing of the village. Rochebrune reaches Mont d''Arbois only by the Chamois gondola and the Rocharbois cable car, and with the Rocharbois closed {{f:F000615|w}} of the journeys between sectors can no longer be made by lift. The Princesse gondola and the Mont Joux chair carry the links to Princesse and Saint-Nicolas in the same way. In Les Portes du Mont-Blanc the three sectors meet around the Christomet, and the Christomet chair and the Bonjournal drag each carry the only lift route for {{f:F000619|w}} of them.',array['F000615','F000619']::text[],'review','loader','network.paras.2'),
('area:evasion-mont-blanc','network','line',0,'{{m:all.rochebrune.saint-gervais}} lift rides','{}'::text[],'review','loader','network.figs.0.v'),
('area:evasion-mont-blanc','network','line',1,'from Rochebrune to Saint-Gervais, and {{m:all.saint-gervais.rochebrune|w}} back','{}'::text[],'review','loader','network.figs.0.t'),
('area:evasion-mont-blanc','network','line',2,'{{m:all.combloux.la-giettaz}} lift rides','{}'::text[],'review','loader','network.figs.1.v'),
('area:evasion-mont-blanc','network','line',3,'from Combloux to La Giettaz, and {{m:all.la-giettaz.combloux|w}} back','{}'::text[],'review','loader','network.figs.1.t'),
('area:evasion-mont-blanc','network','line',4,'No link','{}'::text[],'review','loader','network.figs.2.v'),
('area:evasion-mont-blanc','network','line',5,'by lift or piste between Le Jaillet and Rochebrune; the free Meg-Bus joins them through Megève','{}'::text[],'review','loader','network.figs.2.t'),
('area:evasion-mont-blanc','network','line',6,'{{f:F000615}} journeys',array['F000615']::text[],'review','loader','network.figs.3.v'),
('area:evasion-mont-blanc','network','line',7,'between sectors depend on the Rocharbois cable car above Megève','{}'::text[],'review','loader','network.figs.3.t'),
('area:evasion-mont-blanc','network','line',8,'{{f:F000506}}',array['F000506']::text[],'review','loader','network.figs.4.v'),
('area:evasion-mont-blanc','network','line',9,'Noémie de Rothschild opens the Domaine du Mont d''Arbois','{}'::text[],'review','loader','network.figs.4.t'),
('area:evasion-mont-blanc','network','line',10,'{{f:F000507}}',array['F000507']::text[],'review','loader','network.figs.5.v'),
('area:evasion-mont-blanc','network','line',11,'La Folie Douce opens at the top of Mont Joux, above Saint-Gervais','{}'::text[],'review','loader','network.figs.5.t'),
('area:evasion-mont-blanc','network','heading',1,'Explore the network','{}'::text[],'review','loader','network.mapTitle'),
('area:evasion-mont-blanc','network','caption',0,'Choose a starting point to see how many lift rides it takes to reach each other area, then limit the runs to see what stays within reach.','{}'::text[],'review','loader','network.mapHelp'),
('area:evasion-mont-blanc','network','caption',1,'Schematic, not to scale, with sectors moved apart for legibility. Built from OpenStreetMap lift and piste data (© OpenStreetMap contributors, snapshot 24 October 2026) with heights from the Copernicus 90 m elevation model. An orange link carries routes that no other link replaces when a single lift on it closes. Lift rides are the fewest needed between the lift bases of two areas. The two networks are not linked to each other. The model is being checked against the official 2026/27 piste map.','{}'::text[],'review','loader','network.caption'),
('area:evasion-mont-blanc','network','line',12,'Rochebrune','{}'::text[],'review','loader','sectors.0.short'),
('area:evasion-mont-blanc','network','line',13,'Saint-Gervais','{}'::text[],'review','loader','sectors.3.short'),
('area:evasion-mont-blanc','network','line',14,'Saint-Nicolas','{}'::text[],'review','loader','sectors.4.short'),
('area:evasion-mont-blanc','network','line',15,'Megève','{}'::text[],'review','loader','mapNotes.0.text'),
('area:evasion-mont-blanc','network','line',16,'Mont Joly','{}'::text[],'review','loader','mapNotes.1.text'),
('area:evasion-mont-blanc','routes','heading',0,'Five sample days','{}'::text[],'review','loader','routes.h3'),
('area:evasion-mont-blanc','routes','line',0,'Each trip is counted in lift rides out and back, from the first lift base in each area, with the easiest grade of run that makes it in the map data. The counts start lower than the base table further down, which starts in the village. Time on the pistes, in queues, on foot and on the bus is not included.','{}'::text[],'review','loader','routes.intro'),
('area:evasion-mont-blanc','routes','line',1,'Rochebrune','{}'::text[],'review','loader','routes.rows.0.from'),
('area:evasion-mont-blanc','routes','line',2,'Saint-Gervais','{}'::text[],'review','loader','routes.rows.0.to'),
('area:evasion-mont-blanc','routes','line',3,'Green and blue','{}'::text[],'review','loader','routes.rows.0.grade'),
('area:evasion-mont-blanc','routes','note',0,'Down to Megève, then the Rocharbois cable car and the Mont d''Arbois gondola; home by Les Nants and the Rocharbois again.','{}'::text[],'review','loader','routes.rows.0.note'),
('area:evasion-mont-blanc','routes','line',4,'Mont d''Arbois','{}'::text[],'review','loader','routes.rows.1.from'),
('area:evasion-mont-blanc','routes','line',5,'Saint-Nicolas','{}'::text[],'review','loader','routes.rows.1.to'),
('area:evasion-mont-blanc','routes','line',6,'Red','{}'::text[],'review','loader','routes.rows.1.grade'),
('area:evasion-mont-blanc','routes','note',1,'The way out works on green and blue; leaving Saint-Nicolas needs a red in the map data.','{}'::text[],'review','loader','routes.rows.1.note'),
('area:evasion-mont-blanc','routes','line',7,'Princesse','{}'::text[],'review','loader','routes.rows.2.from'),
('area:evasion-mont-blanc','routes','line',8,'Saint-Gervais','{}'::text[],'review','loader','routes.rows.2.to'),
('area:evasion-mont-blanc','routes','line',9,'Green and blue','{}'::text[],'review','loader','routes.rows.2.grade'),
('area:evasion-mont-blanc','routes','note',2,'Up the Princesse gondolas and down to Le Bettex.','{}'::text[],'review','loader','routes.rows.2.note'),
('area:evasion-mont-blanc','routes','line',10,'Combloux','{}'::text[],'review','loader','routes.rows.3.from'),
('area:evasion-mont-blanc','routes','line',11,'La Giettaz','{}'::text[],'review','loader','routes.rows.3.to'),
('area:evasion-mont-blanc','routes','line',12,'Green and blue','{}'::text[],'review','loader','routes.rows.3.grade'),
('area:evasion-mont-blanc','routes','note',3,'Out by the Crève-Cœur drag and the Christomet chair, home by the Bonjournal drag and the Prés chair.','{}'::text[],'review','loader','routes.rows.3.note'),
('area:evasion-mont-blanc','routes','line',13,'Le Jaillet','{}'::text[],'review','loader','routes.rows.4.from'),
('area:evasion-mont-blanc','routes','line',14,'Combloux','{}'::text[],'review','loader','routes.rows.4.to'),
('area:evasion-mont-blanc','routes','line',15,'Green and blue','{}'::text[],'review','loader','routes.rows.4.grade'),
('area:evasion-mont-blanc','routes','note',4,'One lift each way across the shoulder of the Christomet.','{}'::text[],'review','loader','routes.rows.4.note'),
('area:evasion-mont-blanc','routes','note',5,'Within each network most journeys work on green and blue. The exception is Saint-Nicolas, where every way back towards Megève uses a red. Between the networks there is no ski route at all.','{}'::text[],'review','loader','routes.after'),
('area:evasion-mont-blanc','areas','heading',0,'The eight sectors compared','{}'::text[],'review','loader','areas.h2'),
('area:evasion-mont-blanc','areas','line',0,'Saint-Gervais starts lowest, its lifts leaving the town at {{f:F000570}}, and the Megève sectors and Combloux start between {{f:F000565|n}} and {{f:F000585}}. The tops are modest: only the Mont Joly chair on Mont d''Arbois, at {{f:F000561}}, and the Épaule chair above Saint-Nicolas, at {{f:F000576}}, pass 2,000 m in the map data.',array['F000561','F000565','F000570','F000576','F000585']::text[],'review','loader','areas.intro'),
('area:evasion-mont-blanc','areas','caption',0,'Sectors on the Évasion Mont-Blanc pass','{}'::text[],'review','loader','areas.caption'),
('area:evasion-mont-blanc','areas','line',1,'Sector','{}'::text[],'review','loader','areas.nameLabel'),
('area:evasion-mont-blanc','areas','line',2,'Sectors','{}'::text[],'review','loader','areas.navLabel'),
('area:evasion-mont-blanc','areas','line',3,'Linked to Mont d''Arbois through Megève','{}'::text[],'review','loader','areas.rows.0.net'),
('area:evasion-mont-blanc','areas','note',0,'Includes Côte 2000; the Magic Garden trees lie between the Lanchettes and Radaz lifts.','{}'::text[],'review','loader','areas.rows.0.note'),
('area:evasion-mont-blanc','areas','line',4,'Linked, the hub of the Megève network','{}'::text[],'review','loader','areas.rows.1.net'),
('area:evasion-mont-blanc','areas','note',1,'Reached from Megève by the Chamois gondola; the Mont Joly chair is the highest lift in the area.','{}'::text[],'review','loader','areas.rows.1.note'),
('area:evasion-mont-blanc','areas','line',5,'Linked by the Princesse gondola','{}'::text[],'review','loader','areas.rows.2.net'),
('area:evasion-mont-blanc','areas','note',2,'A large free car park at the foot of the gondola, by Ultimate France''s account.','{}'::text[],'review','loader','areas.rows.2.note'),
('area:evasion-mont-blanc','areas','line',6,'Linked to Mont d''Arbois','{}'::text[],'review','loader','areas.rows.3.net'),
('area:evasion-mont-blanc','areas','note',3,'A gondola climbs from the town to Le Bettex, and the Valléen gondola from the station at Le Fayet.','{}'::text[],'review','loader','areas.rows.3.note'),
('area:evasion-mont-blanc','areas','line',7,'Linked over Mont Joux; the way out needs a red','{}'::text[],'review','loader','areas.rows.4.net'),
('area:evasion-mont-blanc','areas','note',4,'The Épaule chair gives the run down to Saint-Nicolas that Snowcarbon recommends.','{}'::text[],'review','loader','areas.rows.4.note'),
('area:evasion-mont-blanc','areas','line',8,'Linked to Combloux and La Giettaz; no link to Rochebrune','{}'::text[],'review','loader','areas.rows.5.net'),
('area:evasion-mont-blanc','areas','note',5,'The Christomet chair is the meeting point of Les Portes du Mont-Blanc.','{}'::text[],'review','loader','areas.rows.5.note'),
('area:evasion-mont-blanc','areas','line',9,'Linked to Le Jaillet','{}'::text[],'review','loader','areas.rows.6.net'),
('area:evasion-mont-blanc','areas','note',6,'Faces Mont Blanc across the Arve; the village holds the Famille Plus label.','{}'::text[],'review','loader','areas.rows.6.note'),
('area:evasion-mont-blanc','areas','line',10,'Linked to Le Jaillet','{}'::text[],'review','loader','areas.rows.7.net'),
('area:evasion-mont-blanc','areas','note',7,'The Tête du Torraz chair reaches the high point of Les Portes du Mont-Blanc.','{}'::text[],'review','loader','areas.rows.7.note'),
('area:evasion-mont-blanc','areas','note',8,'From the OpenStreetMap lift and piste data (snapshot 24 October 2026) with heights from the Copernicus 90 m elevation model. Green and blue is the share of mapped piste length; drag lifts include platters and T bars as a share of the main lifts. Mapped piste is incomplete, so the shares are useful for comparing sectors but not as totals, and they are being checked against the official 2026/27 piste map.','{}'::text[],'review','loader','areas.note'),
('area:evasion-mont-blanc','terrain','heading',0,'Easy cruising, steep corners','{}'::text[],'review','loader','terrain.h2'),
('area:evasion-mont-blanc','terrain','para',0,'Alti-Mag counts {{f:F000491}} runs on the pass: {{f:F000492}} green, {{f:F000493}} blue, {{f:F000494}} red and {{f:F000495}} black. skiresort.com measures {{f:F000512}} of the linked piste as easy, {{f:F000513}} as intermediate and {{f:F000514}} as difficult.',array['F000491','F000492','F000493','F000494','F000495','F000512','F000513','F000514']::text[],'review','loader','terrain.paras.0'),
('area:evasion-mont-blanc','terrain','para',1,'Green and blue reach almost everything in the map data. Within the Megève network the only gap is Saint-Nicolas, where every route back towards Mont d''Arbois and Megève uses a red, and dropping from Mont d''Arbois to Princesse on easy runs costs one more lift ride. In Les Portes du Mont-Blanc every crossing works on green and blue.','{}'::text[],'review','loader','terrain.paras.1'),
('area:evasion-mont-blanc','terrain','para',2,'The steep ground is in small pockets. Snowcarbon puts the steepest black on the front of Mont Joly, and Côte 2000 above Rochebrune is short and steep. La Giettaz has the largest share of black in the mapped piste, {{f:F000593}}, against {{f:F000563}} on Mont d''Arbois and {{f:F000578}} at Saint-Nicolas.',array['F000563','F000578','F000593']::text[],'review','loader','terrain.paras.2'),
('area:evasion-mont-blanc','terrain','heading',1,'Lift rides between the areas, and the grade they need','{}'::text[],'review','loader','terrain.matrixTitle'),
('area:evasion-mont-blanc','terrain','note',0,'Rows are where the day starts, columns where it goes. A cell marked none has no route by lift and piste: the two networks do not meet. Each other cell shows the fewest lift rides, on green and blue where that works. From the OpenStreetMap piste grades, snapshot 24 October 2026; untagged or wrongly tagged runs can distort the result, and each one is being checked against the official map.','{}'::text[],'review','loader','terrain.matrixNote'),
('area:evasion-mont-blanc','snow','heading',0,'Low villages, a modest top','{}'::text[],'review','loader','snow.h2'),
('area:evasion-mont-blanc','snow','para',0,'This is low skiing by Alpine standards. The lifts start between {{f:F000570|n}} and {{f:F000590}}, and most of the lifts top out below 2,000 m; only the Mont Joly and Épaule chairs climb higher, to {{f:F000561}} and {{f:F000576}} in the map data.',array['F000561','F000570','F000576','F000590']::text[],'review','loader','snow.paras.0'),
('area:evasion-mont-blanc','snow','para',1,'The weather model behind the snowfall figures covers the whole area with one grid cell and adjusts it to three heights. At 1,600 m, close to the middle of the skiing here, a typical season between 1991 and 2020 brought about {{f:F000622}} of snow, more than the cells of the Portes du Soleil and Les 3 Vallées at the same height. At 2,100 m the figure is {{f:F000624}}.',array['F000622','F000624']::text[],'review','loader','snow.paras.1'),
('area:evasion-mont-blanc','snow','para',2,'The trend is down. At 1,600 m the typical season fell from {{f:F000623}} in 1961 to 1990 to {{f:F000622}} in 1991 to 2020, and three of the last five seasons sat in the lowest third of the 76 year record. The lower slopes depend on snowmaking, and the model gives snowfall rather than depth on the ground.',array['F000622','F000623']::text[],'review','loader','snow.paras.2'),
('area:evasion-mont-blanc','snow','para',3,'The season runs from a progressive opening on {{f:F000501|dm}} and a full opening on {{f:F000502|dm}} to {{f:F000503|dm}}. Alti-Mag lists Les Portes du Mont-Blanc as closing earlier, on {{f:F000504|dm}}.',array['F000501','F000502','F000503','F000504']::text[],'review','loader','snow.paras.3'),
('area:evasion-mont-blanc','snow','heading',1,'Lift heights by sector','{}'::text[],'review','loader','snow.heightsTitle'),
('area:evasion-mont-blanc','snow','caption',0,'Lowest lift base to highest lift top in each sector. From OpenStreetMap lift positions and the Copernicus 90 m elevation model.','{}'::text[],'review','loader','snow.heightsCaption'),
('area:evasion-mont-blanc','snow','heading',2,'Seasonal snowfall at three heights, 1950 to 2026','{}'::text[],'review','loader','snow.chartTitle'),
('area:evasion-mont-blanc','snow','caption',1,'Modelled snowfall from November to April, from the ERA5 reanalysis via the Open-Meteo historical weather API, for the grid cell at 45.75 N, 6.75 E adjusted to each height. Dots are single seasons; lines are 11 season running means. These are model values, not measurements on a piste, and the top of the chart lies above the highest lift.','{}'::text[],'review','loader','snow.chartCaption'),
('area:evasion-mont-blanc','snow','line',0,'Modelled snowfall from November to April. Dots are single seasons; lines are 11 season running means. Median 1991 to 2020: {{f:F000622}} at 1,600 m, {{f:F000624}} at 2,100 m, {{f:F000626}} at 2,600 m.',array['F000622','F000624','F000626']::text[],'review','loader','snow.chartDesc'),
('area:evasion-mont-blanc','snow','line',1,'<b>No conditions are reported here yet.</b> The first lifts are due to turn on {{f:F000501}} and the whole area on {{f:F000502}}. Until live data arrives, the official sources below give open lifts, pistes and forecasts.',array['F000501','F000502']::text[],'review','loader','snow.conditions.status'),
('area:evasion-mont-blanc','snow','line',2,'Lifts and pistes open','{}'::text[],'review','loader','snow.conditions.items.0.dt'),
('area:evasion-mont-blanc','snow','line',3,'<a href="https://www.megeve-tourisme.fr/en/">Megève</a> and <a href="https://tourism.saintgervais.com/">Saint-Gervais</a> tourist offices','{}'::text[],'review','loader','snow.conditions.items.0.dd'),
('area:evasion-mont-blanc','snow','line',4,'Mountain forecast','{}'::text[],'review','loader','snow.conditions.items.1.dt'),
('area:evasion-mont-blanc','snow','line',5,'<a href="https://meteofrance.com/meteo-montagne">Météo-France mountain weather</a>','{}'::text[],'review','loader','snow.conditions.items.1.dd'),
('area:evasion-mont-blanc','snow','line',6,'Avalanche danger','{}'::text[],'review','loader','snow.conditions.items.2.dt'),
('area:evasion-mont-blanc','snow','line',7,'<a href="https://meteofrance.com/meteo-montagne">Météo-France bulletins</a> for the Mont Blanc and Aravis massifs, published daily in winter','{}'::text[],'review','loader','snow.conditions.items.2.dd'),
('area:evasion-mont-blanc','snow','line',8,'Terrain beyond the marked pistes is not controlled. The avalanche bulletin and local advice take precedence over anything on this page.','{}'::text[],'review','loader','snow.conditions.safety'),
('area:evasion-mont-blanc','pass','heading',0,'Which pass, and where to buy it','{}'::text[],'review','loader','pass.h2'),
('area:evasion-mont-blanc','pass','para',0,'One pass covers both networks and Les Contamines. Six days cost {{f:F000535}} at the ticket office and {{f:F000536}} bought online at least ten days ahead, a saving of {{diff:F000535,F000536}} for planning early. A day costs {{f:F000534}}.',array['F000534','F000535','F000536']::text[],'review','loader','pass.paras.0'),
('area:evasion-mont-blanc','pass','para',1,'For a week based in Combloux or La Giettaz the local Portes du Mont-Blanc pass covers the smaller network for {{f:F000545}}, {{diff:F000535,F000545}} less than the full pass, though the Megève and Saint-Gervais slopes are then a bus ride and a ticket away.',array['F000535','F000545']::text[],'review','loader','pass.paras.1'),
('area:evasion-mont-blanc','pass','caption',0,'Local pass against the full area pass, adult, 2026/27','{}'::text[],'review','loader','pass.table.caption'),
('area:evasion-mont-blanc','pass','line',0,'Portes du Mont-Blanc, one day','{}'::text[],'review','loader','pass.table.rows.0.0'),
('area:evasion-mont-blanc','pass','line',1,'{{f:F000544}}',array['F000544']::text[],'review','loader','pass.table.rows.0.1'),
