('area:evasion-mont-blanc','pass','note',0,'Sources: <a href="https://guide-ski.fr/?p=8172">Guide Ski for Megève</a>, <a href="https://www.alti-mag.com/domaines-skiables/les-portes-du-mont-blanc">Alti-Mag for Les Portes du Mont-Blanc</a> and <a href="https://tourism.saintgervais.com/i-want-to/an-activity/evasion-mont-blanc-ski-resort-saint-gervais-les-bains-en-4359378/">the Saint-Gervais tourist office</a>.','{}'::text[],'review','loader','pass.table.note'),
