('area:evasion-mont-blanc','fit','line',14,'Good fit','{}'::text[],'review','loader','fit.rows.3.fit'),
('area:evasion-mont-blanc','fit','line',15,'Beginner areas at Petit Rochebrune and Les Marmottons, and a cheap beginner pass in Megève.','{}'::text[],'review','loader','fit.rows.3.why'),
('area:evasion-mont-blanc','fit','line',16,'The lowest slopes depend on snowmaking.','{}'::text[],'review','loader','fit.rows.3.limit'),
