('area:evasion-mont-blanc','fit','line',19,'Children under 5 ski free, a family discount on passes, and Famille Plus in Combloux.','{}'::text[],'review','loader','fit.rows.4.why'),
('area:evasion-mont-blanc','fit','line',20,'Prices for lessons and childcare vary by village and are best checked when booking.','{}'::text[],'review','loader','fit.rows.4.limit'),
('area:evasion-mont-blanc','fit','line',21,'Snowboarders','{}'::text[],'review','loader','fit.rows.5.who'),
('area:evasion-mont-blanc','fit','line',22,'Mixed','{}'::text[],'review','loader','fit.rows.5.fit'),
('area:evasion-mont-blanc','fit','line',23,'A park and boardercross on Mont Joux, and good trees.','{}'::text[],'review','loader','fit.rows.5.why'),
('area:evasion-mont-blanc','fit','line',24,'Drags make up {{f:F000564}} of the main lifts on Mont d''Arbois.',array['F000564']::text[],'review','loader','fit.rows.5.limit'),
('area:evasion-mont-blanc','fit','line',25,'Experts','{}'::text[],'review','loader','fit.rows.6.who'),
('area:evasion-mont-blanc','fit','line',26,'Mixed','{}'::text[],'review','loader','fit.rows.6.fit'),
('area:evasion-mont-blanc','fit','line',27,'Trees, the back of Mont Joly and the steeper slopes of La Giettaz.','{}'::text[],'review','loader','fit.rows.6.why'),
('area:evasion-mont-blanc','fit','line',28,'Only {{f:F000514}} of the piste is rated difficult on skiresort.com.',array['F000514']::text[],'review','loader','fit.rows.6.limit'),
('area:evasion-mont-blanc','fit','line',29,'Putting snow first','{}'::text[],'review','loader','fit.rows.7.who'),
('area:evasion-mont-blanc','fit','line',30,'Poor fit','{}'::text[],'review','loader','fit.rows.7.fit'),
('area:evasion-mont-blanc','fit','line',31,'The modelled snowfall at 1,600 m beats the Portes du Soleil and Les 3 Vallées cells.','{}'::text[],'review','loader','fit.rows.7.why'),
('area:evasion-mont-blanc','fit','line',32,'The lifts climb no higher than {{f:F000511}}, and three of the last five seasons were poor at 1,600 m.',array['F000511']::text[],'review','loader','fit.rows.7.limit'),
('area:evasion-mont-blanc','fit','line',33,'Travelling without a car','{}'::text[],'review','loader','fit.rows.8.who'),
('area:evasion-mont-blanc','fit','line',34,'Good fit','{}'::text[],'review','loader','fit.rows.8.fit'),
('area:evasion-mont-blanc','fit','line',35,'TGV to Sallanches, and a gondola from Saint-Gervais station into the resort.','{}'::text[],'review','loader','fit.rows.8.why'),
('area:evasion-mont-blanc','fit','line',36,'2026/27 bus timetables have not yet been checked.','{}'::text[],'review','loader','fit.rows.8.limit'),
('area:evasion-mont-blanc','fit','line',37,'Preferring a smaller area','{}'::text[],'review','loader','fit.rows.9.who'),
