('area:evasion-mont-blanc','fit','line',39,'Les Portes du Mont-Blanc has its own cheaper pass.','{}'::text[],'review','loader','fit.rows.9.why'),
('area:evasion-mont-blanc','fit','line',40,'It closes earlier than the rest by Alti-Mag''s dates.','{}'::text[],'review','loader','fit.rows.9.limit'),
